<?php require 'config.php';need('sales','ceo');$R=role();
if(post()&&$R==='sales'){$a=$_POST['a']??'';
 if($a==='product')q('INSERT INTO products(name,category,unit_price,stock_qty,reorder_level) VALUES(?,?,?,?,?)',[trim($_POST['name']),trim($_POST['category']),(float)$_POST['unit_price'],(int)$_POST['stock'],(int)$_POST['reorder']]);
 if($a==='purchase'&&(int)$_POST['qty']>0){db()->beginTransaction();q('INSERT INTO purchases(product_id,qty,unit_cost) VALUES(?,?,?)',[(int)$_POST['product_id'],(int)$_POST['qty'],(float)$_POST['unit_cost']]);q('UPDATE products SET stock_qty=stock_qty+? WHERE id=?',[(int)$_POST['qty'],(int)$_POST['product_id']]);db()->commit();}
 if($a==='expense')q('INSERT INTO expenses(description,amount,expense_date) VALUES(?,?,?)',[trim($_POST['description']),(float)$_POST['amount'],$_POST['expense_date']]);
 header('Location: inventory.php');exit;}
top('Inventory & Finance');$f=fin();$P=q('SELECT * FROM products ORDER BY name')->fetchAll();
echo '<div class="grid">';foreach(['Total sales'=>$f['sales'],'Purchases'=>$f['purchases'],'Other expenses'=>$f['expenses'],'Total expenditure'=>$f['spend'],'Profit (sales - expenditure)'=>$f['profit']] as $k=>$v)echo "<div class='stat'><small>$k</small><b>".ugx($v).'</b></div>';echo '</div>';
if($R==='sales'){$opt='';foreach($P as $p)$opt.='<option value="'.$p['id'].'">'.h($p['name']).'</option>';
 echo '<div class="card"><h2>Record purchase (adds stock)</h2><form method="post" class="row">'.tok().'<input type="hidden" name="a" value="purchase"><select name="product_id">'.$opt.'</select><input type="number" name="qty" min="1" placeholder="Qty" required><input type="number" name="unit_cost" min="0" placeholder="Unit cost" required><button>Record</button></form></div>
 <div class="card"><h2>New product</h2><form method="post" class="row">'.tok().'<input type="hidden" name="a" value="product"><input name="name" placeholder="Name" required><input name="category" placeholder="Category"><input type="number" name="unit_price" placeholder="Price" required><input type="number" name="stock" placeholder="Stock" value="0"><input type="number" name="reorder" placeholder="Reorder level" value="5"><button>Add</button></form></div>
 <div class="card"><h2>Record expense</h2><form method="post" class="row">'.tok().'<input type="hidden" name="a" value="expense"><input name="description" placeholder="Description" required><input type="number" name="amount" min="0" placeholder="Amount" required><input type="date" name="expense_date" value="'.date('Y-m-d').'"><button>Record</button></form></div>';}
echo '<div class="card"><h2>Stock</h2><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Reorder at</th></tr>';foreach($P as $p)echo '<tr><td>'.h($p['name']).'</td><td>'.h($p['category']).'</td><td>'.ugx($p['unit_price']).'</td><td>'.$p['stock_qty'].($p['stock_qty']<=$p['reorder_level']?' <span class="b b-high">LOW</span>':'').'</td><td>'.$p['reorder_level'].'</td></tr>';echo '</table></div>';
echo '<div class="card"><h2>Sales</h2><table><tr><th>Date</th><th>Order</th><th>Products</th><th>Survey</th><th>Install</th><th>Total</th></tr>';foreach(q('SELECT * FROM sales ORDER BY id DESC LIMIT 20')->fetchAll() as $s)echo '<tr><td>'.substr($s['sale_date'],0,10).'</td><td>#'.$s['order_id'].'</td><td>'.ugx($s['products_total']).'</td><td>'.ugx($s['survey_fee']).'</td><td>'.ugx($s['install_fee']).'</td><td>'.ugx($s['total']).'</td></tr>';echo '</table></div>';
echo '<div class="card"><h2>Purchases</h2><table><tr><th>Date</th><th>Product</th><th>Qty</th><th>Unit cost</th></tr>';foreach(q('SELECT r.*,p.name FROM purchases r JOIN products p ON p.id=r.product_id ORDER BY r.id DESC LIMIT 20')->fetchAll() as $s)echo '<tr><td>'.substr($s['purchase_date'],0,10).'</td><td>'.h($s['name']).'</td><td>'.$s['qty'].'</td><td>'.ugx($s['unit_cost']).'</td></tr>';echo '</table></div>';
echo '<div class="card"><h2>Expenses</h2><table><tr><th>Date</th><th>Description</th><th>Amount</th></tr>';foreach(q('SELECT * FROM expenses ORDER BY id DESC LIMIT 20')->fetchAll() as $s)echo '<tr><td>'.h($s['expense_date']).'</td><td>'.h($s['description']).'</td><td>'.ugx($s['amount']).'</td></tr>';echo '</table></div>';bottom();
